ga0l(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644\u06ce\u06a9\u06cc \u062f\u0631\u0648\u0633\u062a \u0628\u0646\u0648\u0648\u0633\u06d5."},
ga00(){return"\u0633\u06d5\u06cc\u0631\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06cc \u0646\u0648\u06ce\u062a \u0628\u06a9\u06d5 \u0628\u06c6 \u062f\u06b5\u0646\u06cc\u0627\u0628\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0644\u06d5 \u06af\u06c6\u0695\u06cc\u0646\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644 \u2014 \u0644\u06d5\u0648\u0627\u0646\u06d5\u06cc\u06d5 \u06a9\u06d5\u0645\u06ce\u06a9 \u06a9\u0627\u062a \u0628\u062e\u0627\u06cc\u06d5\u0646\u06ce\u062a."},
